<?php
namespace App\Http\Controllers;use App\Http\Requests\ReturnAssetLoanRequest;use App\Http\Requests\StoreAssetLoanRequest;use App\Models\Asset;use App\Models\AssetLoan;use App\Services\AssetLoanService;use App\Services\AssetNotificationService;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;use Illuminate\View\View;
class AssetLoanController extends Controller{
public function index(Request $request,AssetLoanService $stock):View{$f=$request->validate(['search'=>['nullable','string','max:100'],'status'=>['nullable','in:dipinjam,dikembalikan,terlambat'],'loan_date'=>['nullable','date'],'return_date'=>['nullable','date']]);$q=AssetLoan::with(['asset:id,asset_code,name,photo','creator:id,name']);$q->when($f['search']??null,fn($q,$s)=>$q->where(fn($n)=>$n->where('borrower_name','like',"%{$s}%")->orWhereHas('asset',fn($a)=>$a->where('name','like',"%{$s}%")->orWhere('asset_code','like',"%{$s}%"))))->when(($f['status']??null)==='dikembalikan',fn($q)=>$q->whereNotNull('returned_at'))->when(($f['status']??null)==='dipinjam',fn($q)=>$q->whereNull('returned_at')->where(fn($n)=>$n->whereNull('expected_return_date')->orWhereDate('expected_return_date','>=',today())))->when(($f['status']??null)==='terlambat',fn($q)=>$q->whereNull('returned_at')->whereDate('expected_return_date','<',today()))->when($f['loan_date']??null,fn($q,$d)=>$q->whereDate('loan_date',$d))->when($f['return_date']??null,fn($q,$d)=>$q->whereDate('returned_at',$d));$loans=$q->latest('loan_date')->latest('id')->paginate(10)->withQueryString();$assets=Asset::with(['location:id,name'])->where('status','tersedia')->where('condition','!=','rusak_berat')->orderBy('name')->get()->map(function($asset)use($stock){$asset->available_quantity=$stock->availableQuantity($asset);return $asset;})->filter(fn($asset)=>$asset->available_quantity>0)->values();return view('asset-loans.index',['loans'=>$loans,'assets'=>$assets,'activeCount'=>AssetLoan::whereNull('returned_at')->count(),'returnedThisMonth'=>AssetLoan::whereNotNull('returned_at')->whereYear('returned_at',now()->year)->whereMonth('returned_at',now()->month)->count(),'lateCount'=>AssetLoan::whereNull('returned_at')->whereDate('expected_return_date','<',today())->count()]);}
public function store(StoreAssetLoanRequest $request,AssetLoanService $stock):RedirectResponse{$data=$request->validated();$loan=DB::transaction(function()use($data,$request,$stock){$asset=Asset::lockForUpdate()->findOrFail($data['asset_id']);if($asset->status!=='tersedia'||in_array($asset->status,['perawatan','dihapus'],true))throw ValidationException::withMessages(['asset_id'=>'Aset tidak tersedia untuk dipinjam.']);$available=$stock->availableQuantity($asset);if($data['quantity']>$available)throw ValidationException::withMessages(['quantity'=>"Jumlah pinjam tidak boleh melebihi {$available} unit yang tersedia."]);$loan=AssetLoan::create([...$data,'status'=>'dipinjam','created_by'=>$request->user()->id]);$stock->syncStatus($asset);return $loan;});return redirect()->route('asset-loans.show',$loan)->with('success','Peminjaman aset berhasil disimpan.');}
public function show(AssetLoan $loan):View{return view('asset-loans.show',['loan'=>$loan->load(['asset.location','creator','returner'])]);}
public function returnAsset(ReturnAssetLoanRequest $request,AssetLoan $loan,AssetLoanService $stock,AssetNotificationService $notifications):RedirectResponse{if($loan->returned_at)return back()->withErrors(['return'=>'Aset pada peminjaman ini sudah dikembalikan.']);DB::transaction(function()use($request,$loan,$stock){$asset=Asset::lockForUpdate()->findOrFail($loan->asset_id);$loan->update([...$request->validated(),'status'=>'dikembalikan','returned_by'=>$request->user()->id]);$asset->update(['condition'=>$request->validated('return_condition')]);$stock->syncStatus($asset);});$loan->load('asset');$notifications->admins('Aset Dikembalikan',$loan->asset->name.' telah dikembalikan dalam kondisi '.$loan->return_condition.'.','loan_returned',route('asset-loans.show',$loan),'loan',$loan->id,'loan_returned:'.$loan->id);return redirect()->route('asset-loans.show',$loan)->with('success','Aset berhasil dikembalikan.');}}
